template.query:
mutation BulkImport($input: BulkImportInput!) {
  bulkImport(input: $input) {
    success
    processedCount
    totalCount
    errors {
      line
      message
      severity
    }
    progress {
      percentage
      estimatedTimeRemaining
    }
    summary {
      created
      updated
      skipped
      failed
    }
  }
}
